'use strict';
const sound=window.GameSound,$=id=>document.getElementById(id);let recorder,stream,timer,recording=false,working=false;
const status=s=>$('audio-status').textContent=s;
sound.onError=status;
function button(text,fn){const b=document.createElement('button');b.textContent=text;b.onclick=fn;return b}
function drawLibrary(){
 const library=$('library');library.replaceChildren();if(!sound.clips.length){const p=document.createElement('p');p.textContent='Your first recording goes here. Built-in game sounds are ready to use.';library.append(p)}
 for(const clip of sound.clips){const row=document.createElement('div');row.className='sound-row';const name=document.createElement('span');name.textContent=clip.name;row.append(name,button('▶ Listen',()=>sound.preview(clip.id)),button('Download',()=>{const u=URL.createObjectURL(clip.blob),a=document.createElement('a');a.href=u;const ext=clip.blob.type.includes('mp4')?'m4a':clip.blob.type.includes('ogg')?'ogg':clip.blob.type.includes('wav')?'wav':clip.blob.type.includes('mpeg')?'mp3':'webm';a.download=clip.name.replace(/[^a-z0-9_-]/gi,'_')+'.'+ext;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}),button('Delete',async()=>{if(!confirm('Delete “'+clip.name+'”? Assigned sounds will return to built-in.'))return;try{sound.stop();await sound.remove(clip.id);render();status('Sound deleted')}catch(e){status('Could not delete: '+e.message)}}));library.append(row)}
}
function render(){drawLibrary();const area=$('assignments');area.replaceChildren();for(const [id,name]of Object.entries(sound.events)){const row=document.createElement('div');row.className='sound-row';const label=document.createElement('label');label.textContent=name;label.htmlFor='slot-'+id;const select=document.createElement('select');select.id='slot-'+id;for(const [value,text]of [['builtin','Built-in'],['mute','Silent'],...sound.clips.map(c=>[c.id,c.name])]){const o=document.createElement('option');o.value=value;o.textContent=text;select.append(o)}select.value=sound.settings.slots[id]||'builtin';select.onchange=()=>{try{sound.stop();sound.setSlot(id,select.value);status(name+' saved')}catch(e){status('Could not save your choice: '+e.message)}};row.append(label,select,button('▶ Test',()=>sound.preview(id)));area.append(row)}}
function recordingUI(){ $('record').disabled=working||recording;$('stop-record').disabled=!recording;$('audio-upload').disabled=working||recording}
function release(){clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());stream=null}
function stopRecording(){if(recorder&&recorder.state!=='inactive')recorder.stop();release()}
$('record').onclick=async()=>{
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){status('Microphone recording needs a supported browser on localhost or HTTPS. You can still upload audio.');return}
 working=true;recordingUI();sound.stop();let chunks=[];const name=$('clip-name').value.trim()||'Recording '+new Date().toLocaleTimeString();
 try{stream=await navigator.mediaDevices.getUserMedia({audio:true});recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onerror=()=>{status('Recording failed. Check your microphone and try again.');stopRecording()};recorder.onstop=async()=>{release();recording=false;working=true;recordingUI();try{const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});if(!blob.size)throw Error('No audio was captured');await sound.add(name,blob);render();status('Saved “'+name+'” — choose it below!')}catch(e){status('Could not save recording: '+e.message)}finally{working=false;recordingUI()}};recorder.start();recording=true;timer=setTimeout(stopRecording,120000);status('● Recording… Speak, sing, or make a sound. Press Stop & save when finished.')}catch(e){release();status('Microphone unavailable: '+e.message)}finally{working=false;recordingUI()}
};
$('stop-record').onclick=stopRecording;
$('audio-upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;working=true;recordingUI();try{if(file.size>20*1024*1024)throw Error('Please choose a file smaller than 20 MB');if(!file.size)throw Error('That file is empty');if(file.type&&!file.type.startsWith('audio/'))throw Error('Choose an audio file');const name=$('clip-name').value.trim()||file.name;await sound.add(name,file);render();status('Uploaded “'+name+'”')}catch(err){status('Upload failed: '+err.message)}finally{e.target.value='';working=false;recordingUI()}};
$('stop-preview').onclick=()=>sound.stop();$('volume').oninput=e=>{const v=+e.target.value;$('volume-value').textContent=v+'%';try{sound.setVolume(v/100);sound.stop()}catch(err){status('Could not save volume: '+err.message)}};
window.addEventListener('pagehide',()=>{release();sound.stop()});document.addEventListener('visibilitychange',()=>{if(document.hidden){if(recording)stopRecording();sound.stop()}});
sound.ready.then(()=>{render();$('volume').value=Math.round(sound.settings.volume*100);$('volume-value').textContent=$('volume').value+'%';recordingUI();status('Ready to make some noise!')}).catch(e=>{render();status('Audio library unavailable: '+e.message);$('record').disabled=true;$('audio-upload').disabled=true});

window.InstrumentStudio?.({sound,status,onSaved:render});
